'use client'

import Link from 'next/link'
import { useSession, signOut } from 'next-auth/react'
import { useState } from 'react'
import ThemeToggle from './ThemeToggle'

export default function Navigation() {
  const { data: session, status } = useSession()
  const [isMenuOpen, setIsMenuOpen] = useState(false)

  const handleSignOut = async () => {
    await signOut({ callbackUrl: '/' })
  }

  return (
    <nav className="backdrop-blur bg-[#f8fafc] dark:bg-black shadow-lg rounded-b-xl border-b border-slate-200 dark:border-black sticky top-0 z-50 transition-colors">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          <Link href="/" className="flex items-center">
            <h1 className="text-2xl font-bold text-[#18181b] dark:text-white tracking-tight">🎵 GigRadar</h1>
          </Link>
          
          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-4">
            <Link href="/gigs" className="text-[#18181b] dark:text-white hover:shadow-[0_0_8px_2px_rgba(24,24,27,0.25)] dark:hover:shadow-[0_0_12px_2px_rgba(255,255,255,0.25)] px-3 py-2 rounded-md text-sm font-medium transition-all">
              Discover Gigs
            </Link>
            <Link href="/artists" className="text-[#18181b] dark:text-white hover:shadow-[0_0_8px_2px_rgba(24,24,27,0.25)] dark:hover:shadow-[0_0_12px_2px_rgba(255,255,255,0.25)] px-3 py-2 rounded-md text-sm font-medium transition-all">
              Artists
            </Link>
            <Link href="/venues" className="text-[#18181b] dark:text-white hover:shadow-[0_0_8px_2px_rgba(24,24,27,0.25)] dark:hover:shadow-[0_0_12px_2px_rgba(255,255,255,0.25)] px-3 py-2 rounded-md text-sm font-medium transition-all">
              Venues
            </Link>
            
            {status === 'loading' ? (
              <span className="text-[#18181b] dark:text-white px-3 py-2 text-sm">Loading...</span>
            ) : session ? (
              <div className="flex items-center space-x-4">
                <span className="text-sm text-[#18181b] dark:text-white">
                  Welcome, {session.user?.name || session.user?.email}
                </span>
                <button
                  onClick={handleSignOut}
                  className="text-[#18181b] dark:text-white hover:underline px-3 py-2 rounded-md text-sm font-medium transition-colors"
                >
                  Sign Out
                </button>
              </div>
            ) : (
              <Link href="/login" className="bg-[#18181b] dark:bg-white text-white dark:text-[#0a192f] px-4 py-2 rounded-md text-sm font-medium shadow hover:opacity-90 transition">
                Login
              </Link>
            )}
            <ThemeToggle />
          </div>

          {/* Mobile menu button */}
          <div className="md:hidden flex items-center space-x-2">
            <ThemeToggle />
            <button
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="text-[#18181b] dark:text-white focus:outline-none"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Navigation */}
      {isMenuOpen && (
        <div className="md:hidden bg-[#f8fafc] dark:bg-black border-t border-slate-200 dark:border-black rounded-b-xl">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            <Link href="/gigs" className="text-[#18181b] dark:text-white hover:shadow-[0_0_8px_2px_rgba(24,24,27,0.25)] dark:hover:shadow-[0_0_12px_2px_rgba(255,255,255,0.25)] block px-3 py-2 rounded-md text-base font-medium transition-all">
              Discover Gigs
            </Link>
            <Link href="/artists" className="text-[#18181b] dark:text-white hover:shadow-[0_0_8px_2px_rgba(24,24,27,0.25)] dark:hover:shadow-[0_0_12px_2px_rgba(255,255,255,0.25)] block px-3 py-2 rounded-md text-base font-medium transition-all">
              Artists
            </Link>
            <Link href="/venues" className="text-[#18181b] dark:text-white hover:shadow-[0_0_8px_2px_rgba(24,24,27,0.25)] dark:hover:shadow-[0_0_12px_2px_rgba(255,255,255,0.25)] block px-3 py-2 rounded-md text-base font-medium transition-all">
              Venues
            </Link>
            
            {status === 'loading' ? (
              <span className="text-[#18181b] dark:text-white block px-3 py-2 text-base">Loading...</span>
            ) : session ? (
              <div className="px-3 py-2">
                <p className="text-sm text-[#18181b] dark:text-white mb-2">
                  Welcome, {session.user?.name || session.user?.email}
                </p>
                <button
                  onClick={handleSignOut}
                  className="text-[#18181b] dark:text-white hover:underline block px-3 py-2 rounded-md text-base font-medium transition-colors"
                >
                  Sign Out
                </button>
              </div>
            ) : (
              <Link href="/login" className="bg-[#18181b] dark:bg-white text-white dark:text-[#0a192f] block px-3 py-2 rounded-md text-base font-medium shadow hover:opacity-90 transition">
                Login
              </Link>
            )}
          </div>
        </div>
      )}
    </nav>
  )
} 